create table public.guide_revision_archive (
 guide_id text not null references public.guides,revision text not null check(revision ~ '^[a-f0-9]{24}$'),
 content jsonb not null check(jsonb_typeof(content)='object' and content->>'slug'=guide_id),
 created_at timestamptz not null default now(),primary key(guide_id,revision)
);
alter table public.guide_revision_archive enable row level security;
revoke all on public.guide_revision_archive from public,anon,authenticated;
grant select on public.guide_revision_archive to anon,authenticated;
create policy guide_archive_read on public.guide_revision_archive for select to anon,authenticated using(true);
create function e34_private.immutable_guide_snapshot() returns trigger language plpgsql set search_path='' as $$begin raise exception 'Published guide identities and snapshots are immutable; add a new revision';end$$;
revoke all on function e34_private.immutable_guide_snapshot() from public,anon,authenticated;
create trigger guide_archive_immutable before update or delete on public.guide_revision_archive for each row execute function e34_private.immutable_guide_snapshot();
create trigger guide_step_immutable before update or delete on public.guide_step_index for each row execute function e34_private.immutable_guide_snapshot();
create index guide_progress_guide on public.guide_progress(guide_id);

create function e34_private.moderate_journal_entry(entry uuid,hide boolean,reason text) returns void language plpgsql security definer set search_path='' as $$begin
 if not e34_private.has_role('moderator') or coalesce(auth.jwt()->>'aal','')<>'aal2' then raise exception 'Moderator permission and MFA required';end if;
 if char_length(btrim(reason)) not between 10 and 2000 then raise exception 'Give a moderation reason in 10–2000 characters';end if;
 update public.garage_journal_entries set hidden=hide,updated_at=now() where id=entry;
 if not found then raise exception 'Journal update unavailable';end if;
 insert into e34_private.audit_events(actor_id,action,table_name,record_id,metadata) values(auth.uid(),'journal:moderate','garage_journal_entries',entry::text,jsonb_build_object('hidden',hide,'reason',reason));
end$$;
create function public.moderate_journal_entry(entry uuid,hide boolean,reason text) returns void language sql security invoker set search_path='' as $$select e34_private.moderate_journal_entry(entry,hide,reason);$$;
revoke all on function e34_private.moderate_journal_entry(uuid,boolean,text),public.moderate_journal_entry(uuid,boolean,text) from public,anon,authenticated;
grant execute on function e34_private.moderate_journal_entry(uuid,boolean,text),public.moderate_journal_entry(uuid,boolean,text) to authenticated;

-- Full original editorial snapshots; draft status is preserved.
insert into public.guide_revision_archive(guide_id,revision,content) values
('identify-your-engine','bffabae78e2e7427069e0d7e','{"slug":"identify-your-engine","title":"Identify the engine before choosing a procedure","system":"engine","engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","duration":"5 min read","durationBasis":"Editorial reading or inspection estimate; not a factory labor time","kind":"reference","summary":"Match a car to the manual''s engine families and record what is still unknown before opening a repair or ordering a part.","reviewStatus":"draft","sourceChecked":true,"applicability":"U.S. models: 525i 1989-1995; 535i 1989-1993; 530i and 540i 1994-1995. Applicability within each chapter still varies.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"Foreword p. v; 100-1","pdfPages":[5,43]},"tools":["Vehicle records","Camera or notebook"],"cautions":["A model badge or model year alone does not prove which engine is currently installed.","This source establishes U.S. applications only; a swap needs its own identification evidence."],"steps":[{"title":"Record the actual vehicle","body":"Save the model, market, model year and available production date. Keep an unknown value explicitly unknown.","check":"The vehicle record distinguishes an observed fact from an assumption."},{"title":"Choose a source-supported starting point","body":"The manual groups U.S. 1989-1990 525i with M20, 1991-1992 525i with M50, and 1993-1995 525i with M50TU. Its 535i uses M30, and its 1994-1995 530i/540i use M60.","check":"A starting engine family is selected, or no supported match is claimed."},{"title":"Check the car against its history","body":"Compare the starting point with existing engine identification records and any documented modifications. Resolve a mismatch before using engine-specific instructions.","check":"The guide filter reflects the installed engine or remains unconfirmed."},{"title":"Carry the identity forward","body":"Attach the vehicle and engine family to your repair question and parts inquiry. Verify production restrictions separately before purchasing.","check":"Other members can see the configuration and unresolved details."}]}'::jsonb),
('cooling-system-visual-check','355ab87150fd6bf2a1f95a8b','{"slug":"cooling-system-visual-check","title":"Start an overheating investigation with a cold inspection","system":"cooling","engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","duration":"15-25 min","durationBasis":"Editorial reading or inspection estimate; not a factory labor time","kind":"inspection","summary":"Create a useful first record of coolant loss, belt condition, hoses and radiator airflow before treating a suspected component as a confirmed failure.","reviewStatus":"draft","sourceChecked":true,"applicability":"U.S. models: 525i 1989-1995; 535i 1989-1993; 530i and 540i 1994-1995. Applicability within each chapter still varies.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"170-1 to 170-2","pdfPages":[205,206]},"tools":["Inspection light","Eye protection","Gloves","Notebook or camera"],"cautions":["Wait until the engine and cooling system are fully cold. Never open a hot or pressurized coolant cap.","Keep coolant away from people and animals and contain any spill.","Keep hands clear of fans and belts; the electric fan can operate when the ignition is on."],"steps":[{"title":"Make the work area safe","body":"Park securely, switch the engine and ignition off, and let the system cool completely. This is a visual inspection; do not start a hot-system test.","check":"The engine is off, the key is removed, and the system is cold."},{"title":"Record level and visible leakage","body":"Observe the available cold-level markings and look for wet areas or dried residue around the engine, expansion tank, radiator and hose connections. Do not assume the first wet area is the source.","check":"Each observation has a location and a photo or written description."},{"title":"Look over hoses and the drive belt","body":"Check accessible hoses for cracking or obvious deterioration, inspect clamp areas for leakage, and look at the coolant-pump drive belt for visible damage.","check":"Any damaged or uncertain item is recorded for a closer engine-specific inspection."},{"title":"Inspect the radiator air path","body":"Look for dirt, leaves or debris obstructing the radiator and record any obvious damage. Keep tools and fingers outside the fan area.","check":"The record distinguishes an airflow obstruction from a coolant-flow suspicion."},{"title":"Choose the next test from the evidence","body":"A visual check cannot rule out an internal leak, circulation fault or fan-control fault. Take the recorded observations to the appropriate test or a qualified workshop.","check":"The next action is a test supported by an observation, rather than an unverified parts replacement."}]}'::jsonb),
('cooling-fan-airflow-check','ec0626f718e48c7bed2d7c3e','{"slug":"cooling-fan-airflow-check","title":"Separate an airflow concern from a fan diagnosis","system":"cooling","engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","duration":"10-15 min","durationBasis":"Editorial reading or inspection estimate; not a factory labor time","kind":"inspection","summary":"Understand the mechanical fan and auxiliary electric fan, then gather cold, engine-off observations useful for an overheating-at-idle question.","reviewStatus":"draft","sourceChecked":true,"applicability":"U.S. models: 525i 1989-1995; 535i 1989-1993; 530i and 540i 1994-1995. Applicability within each chapter still varies.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"170-1; 170-3","pdfPages":[205,207]},"tools":["Inspection light","Notebook or camera"],"cautions":["Perform this visual inspection with a cold engine, ignition off and air conditioning off.","Never try to stop a moving fan or reach into its blades.","No powered fan test, connector bridging or hot-engine test is included here."],"steps":[{"title":"Describe when the symptom happens","body":"Record whether the reported overheating happens at idle, in traffic, at speed or under load. The manual identifies primary-fan faults as one possible cause of overheating during prolonged idling.","check":"The report includes conditions and observations without asserting a failed part."},{"title":"Identify the two fan arrangements","body":"From a safe view with the engine off, locate the pump-driven primary fan and the electric auxiliary fan ahead of the radiator. The fan clutch regulates the primary fan coupling.","check":"The question names the fan being discussed instead of using an ambiguous \"fan\" label."},{"title":"Inspect visible condition","body":"Look for damaged blades, obstructions and visible fluid leakage near the viscous clutch. Record what is visible without reaching into the fan assembly.","check":"Photos or notes identify the observed issue and its location."},{"title":"Escalate to the appropriate controlled test","body":"A still fan alone is not proof of a fault. Use the engine-specific fan-check procedure and wiring evidence for the next test, or ask a workshop to perform it.","check":"The next test is chosen; the observation has not been marked as a verified diagnosis."}]}'::jsonb),
('m50-water-pump-job-planning','a0ebe9e0e41c6f2c55976074','{"slug":"m50-water-pump-job-planning","title":"Plan an M50 coolant-pump job","system":"cooling","engines":["M50","M50TU"],"level":"Intermediate","duration":"10 min planning","durationBasis":"Editorial reading or inspection estimate; not a factory labor time","kind":"planning","summary":"Prepare the correct engine-specific procedure, access tools and sealing parts before beginning coolant-pump work. This checklist is job planning, not a stand-alone replacement procedure.","reviewStatus":"draft","sourceChecked":true,"applicability":"U.S. models: 525i 1989-1995; 535i 1989-1993; 530i and 540i 1994-1995. Applicability within each chapter still varies.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"170-8 to 170-9","pdfPages":[212,213]},"tools":["Full engine-specific service procedure","Parts and tool checklist","Coolant containment plan"],"cautions":["Do not open or drain a hot cooling system.","The fan-clutch attachment uses a left-hand thread; consult the proper removal procedure before applying force.","Installation loads, tightening specifications, coolant choice and bleeding must be verified for the actual vehicle and replacement parts."],"steps":[{"title":"Confirm the M50 application","body":"Check the installed engine identity and review the M50-specific pump procedure rather than borrowing the M20, M30 or M60 steps.","check":"The engine and any modification are recorded."},{"title":"Plan access before draining","body":"The source procedure requires attention to the fan and shroud, coolant hoses, belt and pump pulley. Check that the required access tools and complete instructions are available.","check":"The work can proceed safely without improvising a missing holding or access tool."},{"title":"Match the pump and sealing parts","body":"Verify the pump application and obtain the correct new seal. This page does not supply a proven OEM number or current manufacturer material recommendation.","check":"The replacement and seal have documented fitment for the car."},{"title":"Preserve the installation cautions","body":"The source warns that drawing the pump in unevenly can damage the pump or timing-chain cover. Keep the complete tightening sequence and specifications with the job.","check":"The installer has the full method and vehicle-specific specifications."},{"title":"Plan completion checks","body":"The source calls for refilling and bleeding after reassembly. Include leak checks, coolant-level rechecks and a controlled functional check in the full work plan.","check":"The job checklist includes completion verification rather than ending when the new part is installed."}]}'::jsonb),
('battery-connections-first-check','3b60d5c1f6145f24b09ade71','{"slug":"battery-connections-first-check","title":"Inspect battery cables and grounds before blaming the alternator","system":"electrical","engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","duration":"15 min","durationBasis":"Editorial reading or inspection estimate; not a factory labor time","kind":"inspection","summary":"Gather the basic connection, ground and belt observations that help a charging or slow-cranking investigation.","reviewStatus":"draft","sourceChecked":true,"applicability":"U.S. models: 525i 1989-1995; 535i 1989-1993; 530i and 540i 1994-1995. Applicability within each chapter still varies.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"121-1","pdfPages":[163]},"tools":["Inspection light","Eye protection","Gloves","Notebook or camera"],"cautions":["Battery acid and explosive charging gas require eye and skin protection and no sparks, smoking or flame.","Do not bridge battery terminals with tools or jewelry.","This page does not instruct battery disconnection, charging or live electrical testing."],"steps":[{"title":"Find the battery for this configuration","body":"The source locates it in the engine compartment on U.S. 1989-1991 525i and under the rear seat on 1992-on 525i and the covered 530i, 535i and 540i. Confirm the actual installation.","check":"The location is observed on the car and any modification is recorded."},{"title":"Inspect without disturbing the connections","body":"With the ignition off, look for visible corrosion, cable damage and an obviously loose connection. Avoid touching both terminals or placing a tool between a terminal and bodywork.","check":"Visible connection issues are documented, not hidden by an immediate parts swap."},{"title":"Follow the ground path visually","body":"Inspect accessible battery-to-body and engine-to-body ground connections for damage or corrosion. Do not infer electrical continuity from appearance alone.","check":"The report identifies which ground connection was observed."},{"title":"Check the alternator belt visually","body":"With the engine stopped, inspect the accessible belt for obvious wear or damage. Belt adjustment and replacement require the applicable engine procedure.","check":"Belt condition is recorded separately from battery or alternator condition."},{"title":"Request the next measurement","body":"If the cause remains unclear, use a suitable charging-system diagnostic procedure or workshop test. A visual inspection alone cannot certify battery capacity or alternator output.","check":"The next step is a defined measurement with the vehicle identity attached."}]}'::jsonb),
('front-strut-component-identification','d42647ea4f23a5c5480bb16f','{"slug":"front-strut-component-identification","title":"Identify a front strut assembly and its production differences","system":"suspension","engines":["M20","M30","M50","M50TU","M60"],"level":"Beginner","duration":"8 min read","durationBasis":"Editorial reading or inspection estimate; not a factory labor time","kind":"reference","summary":"Learn the front-suspension component names and why the upper strut stack must be checked against the car''s configuration.","reviewStatus":"draft","sourceChecked":true,"applicability":"U.S. models: 525i 1989-1995; 535i 1989-1993; 530i and 540i 1994-1995. Applicability within each chapter still varies.","source":{"id":"bentley-e34-upload","title":"BMW 5 Series (E34) Service Manual","section":"310-1 to 310-4","pdfPages":[277,278,279,280]},"tools":["Vehicle production information","Parts diagram or camera"],"cautions":["Do not loosen the strut shaft nut or disassemble a spring-loaded assembly for identification.","Spring work requires suitable equipment and the complete procedure.","Do not treat a visual teaching diagram as a fitment guarantee."],"steps":[{"title":"Distinguish the nearby components","body":"The front suspension includes the strut, control arm, thrust arm, stabilizer link, crossmember and center tie rod. Use these names to locate the subject of a noise or parts question.","check":"The report identifies a component or clearly states that its location is uncertain."},{"title":"Read the strut as an assembly","body":"The strut stack includes the mount, spring seats and pads, spring, cartridge and housing; the bump stop and protective tube are additional service items.","check":"The requested item is not confused with the entire strut assembly."},{"title":"Check the production split","body":"The manual shows different upper stacks for 1989-1992 and 1993-on applications. It also notes that some mounts correct camber and carry a plus or minus marking.","check":"Production information and any observed mount marking are included with the inquiry."},{"title":"Verify fitment before ordering","body":"Check the car''s actual strut and mount configuration, including prior modifications, against documented parts applicability. The source diagram does not establish an OEM number for every item.","check":"The part remains unconfirmed until the vehicle and catalog evidence agree."}]}'::jsonb)
on conflict do nothing;
